// Rejects anyone who doesn't know GHL_WEBHOOK_SECRET.
// Accepted in the X-GHL-Secret header (Custom Webhook action) or as "secret" in Custom Data (plain Webhook action).
const j = $input.first().json;
const expected = $env.GHL_WEBHOOK_SECRET || '';
const received = j.headers?.['x-ghl-secret'] || j.body?.customData?.secret || j.body?.secret || '';
if (expected && received !== expected) {
  throw new Error('Unauthorized: bad or missing secret');
}
return $input.all();

// Turns whatever GHL sends into a tidy WhatsApp message.
//
// Special keys (all optional):
//   title    heading of the message, e.g. "Strategy Call Booked"
//   emoji    shown before the title (default 🔔)
//   to       who gets it: 64211234567@c.us, a group 120363...@g.us, a plain number,
//            or several separated by commas. Falls back to WHATSAPP_TO in .env
//   message  send this exact text instead of building one
//   secret   only used by "Validate secret", never shown
//
// EVERY OTHER KEY becomes a line in the message, in the order you wrote it:
//   "booked_for": "Thu 10am"   ->   *Booked For*
//                                    Thu 10am
// Blank values are skipped, so one workflow serves every alert you build.

const RESERVED = ['title', 'emoji', 'to', 'message', 'secret'];
const raw = $input.first().json.body || {};

// Two GHL actions, two shapes:
//  - Custom Webhook: the JSON body you wrote -> use all of it
//  - plain Webhook : the whole contact record + your Custom Data under "customData"
//                    -> use only name/email/phone + your Custom Data, not the 50 other contact fields
let b;
if (raw.customData && typeof raw.customData === 'object') {
  b = {
    name: raw.full_name || [raw.first_name, raw.last_name].filter(Boolean).join(' '),
    email: raw.email,
    phone: raw.phone,
    ...raw.customData,
  };
} else {
  b = raw;
}

const isBlank = (v) => {
  if (v == null) return true;
  const s = String(v).trim();
  return s === '' || s === 'null' || s === 'undefined' || s === 'None';
};

// "booked_for" / "bookedFor" / "Booked For" -> "Booked For"
const label = (k) => String(k)
  .replace(/([a-z])([A-Z])/g, '$1 $2')
  .replace(/[_-]+/g, ' ')
  .replace(/\b\w/g, (c) => c.toUpperCase());

// GHL escapes real newlines in merge fields as the literal "\n". Turn them back into line breaks.
const unescape = (v) => (typeof v === 'object' ? JSON.stringify(v) : String(v))
  .replace(/\\r\\n/g, '\n').replace(/\\n/g, '\n');

const lines = Object.entries(b)
  .filter(([k, v]) => !RESERVED.includes(k) && !isBlank(v))
  .map(([k, v]) => `*${label(k)}*\n${unescape(v)}`)
  .join('\n\n');

const heading = `${b.emoji || '🔔'} *${b.title || 'New GHL Alert'}*`;
const message = b.message || (lines ? `${heading}\n\n${lines}` : heading);

// One output item per recipient -> the next node sends one WhatsApp each.
const recipients = String(b.to || $env.WHATSAPP_TO || '')
  .split(',')
  .map((t) => t.trim())
  .filter(Boolean)
  .map((t) => (t.includes('@') ? t : t.replace(/\D/g, '') + '@c.us'));

if (!recipients.length) throw new Error('No recipient: set WHATSAPP_TO in .env or send "to"');

return recipients.map((chatId) => ({ json: { message, chatId } }));
